body.script:
(function () {
  var frame = document.getElementById("astra");
  var b = atob(document.getElementById("astra-page").textContent.trim());
  var bytes = new Uint8Array(b.length);
  for (var i = 0; i < b.length; i++) bytes[i] = b.charCodeAt(i);
  frame.srcdoc = new TextDecoder().decode(bytes);
  frame.focus();
})();
